-- ------------------------------------------------------------------------------
-- 1. Storage Buckets Privacy Enforcement
-- ------------------------------------------------------------------------------
-- Lock down both course-assets and submissions buckets as strictly private
update storage.buckets
set public = false
where id in ('course-assets', 'submissions');

