      p_payment_id,
      jsonb_build_object(
        'order_id', p_order_id,
        'payment_id', p_payment_id,
        'cohort_id', p_cohort_id,
        'user_id', p_user_id,
        'amount', p_amount,
        'duplicate_enrollment_prevented', true
      )
    );

    return jsonb_build_object(
      'success', true,
      'already_processed', false,
      'duplicate_prevented', true,
      'payment_id', p_payment_id,
      'enrollment_id', coalesce(v_existing_enrollment.id::text, p_user_id::text || '_' || p_cohort_id::text),
      'status', 'captured'
    );
  end if;

  -- [F] Record Captured Payment
  if v_existing_payment.id is not null then
    update public.payments
    set payment_id = p_payment_id,
        signature = coalesce(p_signature, signature),
        status = 'captured',
        metadata = coalesce(public.payments.metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb),
        updated_at = now()
    where order_id = p_order_id;
  else
    insert into public.payments (
      order_id,
      payment_id,
      signature,
      cohort_id,
      user_id,
      amount,
      currency,
      status,
      provider,
      metadata,
      updated_at
    )
    values (
      p_order_id,
      p_payment_id,
      p_signature,
      p_cohort_id,
      p_user_id,
      p_amount,
      coalesce(p_currency, 'INR'),
      'captured',
      'razorpay',
      coalesce(p_metadata, '{}'::jsonb),
